ng-left:2rem}.comment-iframe{background-color:var(--bg-post);padding:1.5rem;border-radius:20px;border:1px solid var(--color-border);margin-bottom:2rem}.comment-iframe iframe{width:100%!important}.comment-restore-button{border:1px solid var(--color-border);width:100%;padding:1rem;border-radius:12px;font-family:"Figtree",sans-serif;font-weight:600;margin-top:1rem}.footer{text-align:center;margin-top:2.5rem}.form-label{margin-bottom:var(--form-gap);display:block}.form-section:not(:first-child){margin-top:1.5rem}.form-control{padding:var(--form-padding);border:1px solid var(--color-border);width:100%}.form-control:focus{border-color:var(--primary);outline:none}.header{text-align:center;background:var(--body-background);background-size:cover;background-color:var(--body-background-color);padding:.75rem 0;position:fixed;top:15px;left:50%;transform:translateX(-50%);width:calc(100% - 40px);max-width:var(--container);z-index:100;border-radius:50px;box-shadow:0 10px 30px rgb(0 0 0 / .1)}.header-logo{justify-content:center;display:flex}.header-title{font-size:1.75rem}.header-title a{color:var(--color-header-title)}.header-subtitle{color:var(--color-header-subtitle);font-size:1.25rem}.header-bars{left:2rem}.header-bars:before{pointer-events:var(--switch-bars,none);opacity:var(--switch-bars,0)}.header-search{right:2rem}.header-search:before{pointer-events:var(--switch-search,none);opacity:var(--switch-search,0)}.header .google-auto-placed{display:none!important}.i{stroke-width:var(--i-stroke,2);width:var(--i-size,20px);height:var(--i-size,20px);stroke:currentColor;stroke-linecap:round;stroke-linejoin:round;fill:none;display:inline-block;vertical-align:middle;margin-right:8px}.message{text-align:center;font-size:1.25rem}.blog-pager{justify-content:center;gap:1rem;margin-top:2.5rem;display:flex}.pager-button{color:var(--color-text);border:1px solid var(--color-border);align-items:center;gap:.5rem;padding:.75rem;display:flex}.pager-button:hover{color:var(--primary)}.post{max-width:7